
(function(){'use strict';
var running=false,last=0,endpoint=new URL('api/inventory-share',location.href);
async function api(action,body){var response=await fetch(endpoint,{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.assign({action:action},body||{}))});if(!response.ok)throw new Error('unavailable');return response.json();}
async function refresh(){var shell=window.VerdictUnifiedShell,context=shell&&shell.getContext();if(running||document.hidden||!shell||!shell.notifications||!context||context.demo||Date.now()-last<15000)return;running=true;last=Date.now();try{var all=await api('bootstrap'),workspaces=all.workspaces.filter(function(w){return w.role==='owner';});for(var w of workspaces){if(w.sourceSiteId!==context.siteId)continue;localStorage.setItem('verdict:inventory:link:'+w.sourceSiteId,JSON.stringify({id:w.id,name:w.name,sourceSiteId:w.sourceSiteId}));var r=await api('summary',{workspaceId:w.id}),items=[];for(var event of r.submissions)items.push({id:'inventory-r32:'+w.id+':'+event.id,source:'Inventaire',module:'inventory',level:'info',actorName:event.actor,establishmentId:w.sourceSiteId,establishmentName:w.name,title:'Comptage de l’équipe reçu',detail:(event.summary?event.summary.counted+' / '+event.summary.total+' références comptées. ':'')+'Consultez la situation reçue.',proof:'Comptage transmis et enregistré par le serveur.',createdAt:event.createdAt});for(var alert of r.summary.alerts){if(alert.status!=='empty'&&alert.status!=='low')continue;items.push({id:'inventory-r32:'+w.id+':'+alert.id+':'+alert.countedAt+':'+alert.quantity,source:'Inventaire',module:'inventory',level:alert.status==='empty'?'critical':'warning',establishmentId:w.sourceSiteId,establishmentName:w.name,title:alert.status==='empty'?'Zéro confirmé : '+alert.name:'Sous le minimum : '+alert.name,detail:alert.quantity+' '+alert.unit+' comptés · minimum '+alert.minimum+'.',proof:'Quantité renseignée dans un comptage reçu de moins de 24 h.',createdAt:alert.countedAt});}shell.notifications.ingestMany(items);}}catch(e){}finally{running=false;}}
window.addEventListener('focus',refresh);document.addEventListener('visibilitychange',refresh);window.addEventListener('load',function(){setTimeout(refresh,2500);});window.addEventListener('message',function(e){if(e.origin===location.origin&&e.data&&e.data.type==='verdict-unified-context')refresh();});
})();

